inference_output.content:
Below is a compact “recipe” you can drop into any back‑end (Node, Python, Go, etc.) that will:

1. **Detect the visitor’s IP address** (usually from the request headers).  
2. **Ask the greeting‑service for a locale‑specific greeting** using that IP.  
3. **Fall back to the browser‑language greeting** if the IP‑lookup fails or returns an unsupported language.  

---

## 1. High‑level flow

```
request ──► extract client IP
          │
          ▼
getGreetingByIP(ip) ──► { greeting, language }
          │
          ├─► success → return greeting
          │
          ▼
fallback → getGreeting(browserLang) → { greeting }
          │
          ▼
return greeting
```

*If the IP‑based service can’t determine a location (e.g., private IP, VPN, or the IP isn’t in its database) you simply ask the “browser‑language” endpoint, which uses the `Accept‑Language` header or the language code you pass.*

---

## 2. Example implementation (Node / Express)

```js
// ------------------------------------------------------------
// 1️⃣  Install the HTTP client you like (axios, node-fetch, …)
// ------------------------------------------------------------
const axios = require('axios');

// ------------------------------------------------------------
// 2️⃣  Helper: pull the real client IP from the request
// ------------------------------------------------------------
function getClientIp(req) {
  // Most CDNs / proxies set X-Forwarded-For; fall back to connection remote address
  const forwarded = req.headers['x-forwarded-for'];
  if (forwarded) {
    // X-Forwarded-For can be a comma‑separated list – the first one is the original client
    return forwarded.split(',')[0].trim();
  }
  return req.socket?.remoteAddress;
}

// ------------------------------------------------------------
// 3️⃣  Wrapper around the greeting API
// ------------------------------------------------------------
async function fetchGreetingByIp(ip) {
  try {
    const resp = await axios.post(
      'https://api.example.com/getGreetingByIP',   // <-- replace with the real endpoint
      { ip }
    );
    // Expected shape: { greeting: "¡Hola!", language: "es" }
    return resp.data;
  } catch (e) {
    // Anything that prevents a proper response (network, 4xx/5xx, etc.)
    console.warn('IP‑greeting lookup failed:', e.message);
    return null;
  }
}

async function fetchGreetingByLang(lang) {
  try {
    const resp = await axios.post(
      'https://api.example.com/getGreeting',   // <-- replace with the real endpoint
      { language: lang }                       // omit the field for auto‑detect
    );
    // Expected shape: { greeting: "Hello!" }
    return resp.data;
  } catch (e) {
    console.error('Language‑greeting lookup failed:', e.message);
    return { greeting: 'Hello!' }; // ultimate fallback
  }
}

// ------------------------------------------------------------
// 4️⃣  The actual Express route
// ------------------------------------------------------------
app.get('/greet', async (req, res) => {
  const ip = getClientIp(req);
  let result = null;

  // ① Try IP‑based greeting first
  if (ip) {
    result = await fetchGreetingByIp(ip);
  }

  // ② If IP failed, fall back to the browser language
  if (!result) {
    const browserLang = req.headers['accept-language']?.split(',')[0] || undefined;
    result = await fetchGreetingByLang(browserLang);
  }

  // ③ Send the greeting back (you could also embed it in HTML, JSON, etc.)
  res.json({ greeting: result.greeting });
});
```

### What the code does

| Step | Action | Why it matters |
|------|--------|----------------|
| **Extract IP** | `getClientIp` reads `X‑Forwarded‑For` (most CDNs set it) or the raw socket address. | Guarantees you’re using the *real* client IP, not the server’s own address. |
