3. **Make API calls** (example in Node.js/Express)

```js
const axios = require('axios');
const qs = require('querystring');

// Exchange auth code for token
async function getAccessToken(code) {
  const response = await axios.post('https://api.soundcloud.com/oauth2/token',
    qs.stringify({
      client_id:     process.env.SC_CLIENT_ID,
      client_secret: process.env.SC_CLIENT_SECRET,
      redirect_uri:  process.env.SC_REDIRECT_URI,
      grant_type:    'authorization_code',
      code:          code
    })
  );
  return response.data.access_token;
}

// Example: add a track to the user's favorites
