4. **Upload a track** (requires `publish` scope)

```js
async function uploadTrack(accessToken, filePath, title, genre = 'Unknown') {
  const FormData = require('form-data');
  const fs = require('fs');
  const form = new FormData();

  form.append('track[title]', title);
  form.append('track[genre]', genre);
  form.append('track[asset_data]', fs.createReadStream(filePath));

  const response = await axios.post(
    'https://api.soundcloud.com/tracks',
    form,
    {
      headers: {
        Authorization: `OAuth ${accessToken}`,
        ...form.getHeaders()
      }
    }
  );
  return response.data; // contains the new track ID, permalink, etc.
}
```

